function guide({ title, slug, os, version, category, path, steps, keywords = [], aliases = [], description, source_url, related_slugs = [], caution, impact, rollback, difficulty = "beginner", estimate_minutes = 3, device_scope }) {
  return {
    title,
    slug,
    os,
    version,
    category,
    aliases: aliases.length ? aliases : [title],
    path,
    steps,
    related_slugs,
    keywords: keywords.length ? keywords : [title],
    description: description || `${title}の設定方法です。`,
    source_url,
    verified_at: VERIFIED_AT,
    review_due_at: REVIEW_DUE_AT,
    difficulty,
    estimate_minutes,
    device_scope: device_scope || `${version}の標準的な設定画面を基準にしています。機種・更新状況により表示が異なる場合があります。`,
    ...(caution ? { caution } : {}),
    ...(impact ? { impact } : {}),
    ...(rollback ? { rollback } : {}),
  };
}

